"0.5rem", "full": "0.75rem" }, "spacing": { "margin": "1rem", "space-sm": "0.5rem", "space-lg": "1.5rem", "space-xl": "3rem", "space-md": "1rem", "space-xs": "0.25rem", "gutter": "1.5rem" }, "fontFamily": { "display-hero-mobile": [ "Inter" ], "display-hero": [ "Inter" ], "label-md": [ "Inter" ], "body-lg": [ "Inter" ], "body-md": [ "Inter" ], "headline-lg": [ "Inter" ], "headline-sm": [ "Inter" ], "label-sm": [ "Inter" ], "body-sm": [ "Inter" ], "title-md": [ "Inter" ], "headline-md": [ "Inter" ], "headline-lg-mobile": [ "Inter" ] }, "fontSize": { "display-hero-mobile": [ "32px", { "lineHeight": "40px", "letterSpacing": "-0.01em", "fontWeight": "700" } ], "display-hero": [ "48px", { "lineHeight": "56px", "letterSpacing": "-0.02em", "fontWeight": "700" } ], "label-md": [ "14px", { "lineHeight": "20px", "letterSpacing": "0.01em", "fontWeight": "600" } ], "body-lg": [ "18px", { "lineHeight": "28px", "fontWeight": "400" } ], "body-md": [ "16px", { "lineHeight": "24px", "fontWeight": "400" } ], "headline-lg": [ "36px", { "lineHeight": "44px", "letterSpacing": "-0.015em", "fontWeight": "700" } ], "headline-sm": [ "22px", { "lineHeight": "30px", "fontWeight": "600" } ], "label-sm": [ "12px", { "lineHeight": "16px", "letterSpacing": "0.02em", "fontWeight": "600" } ], "body-sm": [ "14px", { "lineHeight": "20px", "fontWeight": "400" } ], "title-md": [ "18px", { "lineHeight": "26px", "fontWeight": "600" } ], "headline-md": [ "28px", { "lineHeight": "36px", "fontWeight": "600" } ], "headline-lg-mobile": [ "26px", { "lineHeight": "34px", "letterSpacing": "-0.01em", "fontWeight": "700" } ] } } } };</script></head><body class="min-h-screen bg-background font-body-md text-body-md text-on-surface antialiased flex flex-col justify-between"><main class="w-full flex-1 flex flex-col items-center justify-center p-space-md sm:p-space-lg"><div class="flex flex-col w-full items-center justify-center py-space-xl px-space-md">
<div class="w-full max-w-[440px] bg-surface-container-lowest shadow-sm rounded-xl p-space-lg md:p-space-xl">
<div class="flex flex-col items-center mb-space-lg text-center">
<div class="flex items-center justify-center mb-space-md">
<img alt="EMAB Electrical Logo" class="h-16 w-auto object-contain" src="https://lh3.googleusercontent.com/aida-public/AB6AXuDSS0zIcctWxi120tr6xm3y5O8rofV-_-s4d5uNL_jHYr7UN-X8JNTiSGDhYGADkasK3BRlK7JQMh9aGyd37bwMO6ayxJij_I6HJZznLgis9DgdGzKkaMNRhy4va9ciBkAjp2kUo8VBnkA3FUbAiBvXn4DuOkjE5aVUC3cM71GpJBddOHxfwKNmL4AD9RxyAoM_9CAx9Nz8ZPOnwHV85KOsQ-cZXv6mtM5ouFgH4hg46MItCtgiR8so9gDI-m5X6nyxwaQ"/>
</div>
<h1 class="font-headline-md text-headline-md text-on-surface tracking-tight mb-space-xs">
        Admin Login
      </h1>
<p class="font-body-sm text-body-sm text-secondary">
        Sign in to manage EMAB Electrical portal
      </p>
</div>
<form class="space-y-space-md" onsubmit="event.preventDefault();">
<div class="flex flex-col gap-space-xs">
<label class="font-label-md text-label-md text-on-surface" for="admin-email">
          Email address
        </label>
<div class="relative flex items-center">
<input class="w-full h-10 px-space-md bg-surface-container-low text-on-surface font-body-sm text-body-sm rounded-lg focus:outline-none focus:bg-surface-container-lowest transition-colors placeholder:text-outline" id="admin-email" name="email" placeholder="admin@emab.co.ke" required="" type="email"/>
</div>
</div>
<div class="flex flex-col gap-space-xs">
<label class="font-label-md text-label-md text-on-surface" for="admin-password">
          Password
        </label>
<div class="relative flex items-center">
<input class="w-full h-10 pl-space-md pr-12 bg-surface-container-low text-on-surface font-body-sm text-body-sm rounded-lg focus:outline-none focus:bg-surface-container-lowest transition-colors placeholder:text-outline" id="admin-password" name="password" placeholder="••••••••••••" required="" type="password"/>
<button aria-label="Toggle password visibility" class="absolute right-0 top-0 bottom-0 px-space-md flex items-center justify-center text-secondary hover:text-primary transition-colors focus:outline-none" id="toggle-password" type="button">
<span class="material-symbols-outlined text-title-md select-none" id="eye-icon">visibility</span>
</button>
</div>
</div>
<div class="flex items-center justify-between pt-space-xs">
<label class="flex items-center gap-space-xs cursor-pointer select-none">
<input class="w-4 h-4 rounded-lg bg-surface-container-low text-primary accent-primary cursor-pointer" id="remember-me" type="checkbox"/>
<span class="font-body-sm text-body-sm text-secondary">
            Remember me
          </span>
</label>
<a class="font-label-md text-label-md text-primary hover:text-on-primary-fixed-variant transition-colors" href="#">
          Forgot password?
        </a>
</div>
<div class="pt-space-xs">
<button class="w-full h-11 bg-primary hover:bg-primary-container text-on-primary font-label-md text-label-md rounded-lg shadow-sm transition-colors flex items-center justify-center gap-space-xs" type="submit">
<span>Sign In</span>
</button>
</div>
</form>
</div>
<div class="mt-space-lg text-center">
<a class="inline-flex items-center gap-space-xs font-body-sm text-body-sm text-secondary hover:text-primary transition-colors group" href="#">
<span class="material-symbols-outlined text-body-sm group-hover:-translate-x-0.5 transition-transform">arrow_back</span>
<span>Back to website</span>
</a>
</div>
<script>
    (function() {
      const toggleBtn = document.getElementById('toggle-password');
      const passwordInput = document.getElementById('admin-password');
      const eyeIcon = document.getElementById('eye-icon');

      if (toggleBtn && passwordInput && eyeIcon) {
        toggleBtn.addEventListener('click', function() {
          const isPassword = passwordInput.getAttribute('type') === 'password';
          passwordInput.setAttribute('type', isPassword ? 'text' : 'password');
          eyeIcon.textContent = isPassword ? 'visibility_off' : 'visibility';
        });
      }
    })();
  </script>
</div></main><footer class="w-full py-space-md bg-transparent text-center"><div class="max-w-7xl mx-auto px-space-md text-on-surface-variant font-body-sm text-body-sm">© 2025 EMAB Electrical Engineering &amp; Contracting. Authorized Admin Portal.</div></footer></body></html>